ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| NOT UserName=/\$$/
| regex("(?i)(bcdedit.*(safeboot|recoveryenabled)|vssadmin.*delete.*shadow|wmic.*shadowcopy.*delete|Set-MpPreference.*Disable(Realtime|Behavior|Script|IOAV)Monitoring)", field=CommandLine)
| case {
    regex("(?i)bcdedit", field=CommandLine) | Technique := "SafeBootOrRecoveryOff";
    regex("(?i)vssadmin|shadowcopy", field=CommandLine) | Technique := "ShadowDelete";
    regex("(?i)MpPreference", field=CommandLine) | Technique := "DefenderDisable";
    * | Technique := "Other";
  }
| groupBy([aid, ComputerName, bucket(span=1h)],
          function={ collect([Technique, CommandLine, ParentBaseFileName], multival=true) | count(field=Technique, distinct=true, as=DistinctTechniques) | min(@timestamp, as=FirstSeen) | max(@timestamp, as=LastSeen) })
| DistinctTechniques >= 2
